"""Weekly timesheet lines built from a list of shifts."""

from typing import Iterable, List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to report on")
    if any(not shift.worker.strip() for shift in shifts):
        raise ValueError("shift with a blank worker name")


def _counts(shifts: List[Shift]) -> dict:
    counts = {}
    for shift in shifts:
        counts[shift.worker] = counts.get(shift.worker, 0) + 1
    return counts


# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, like Brisa: 2 shifts, 8.5 hours, busiest first."""
    shifts = list(shifts)
    _check(shifts)
    counts, minutes = _counts(shifts), worker_minutes(shifts)
    order = sorted(minutes, key=lambda name: (-minutes[name], name))
    return [f"{n}: {counts[n]} shifts, {minutes[n] / 60:.1f} hours" for n in order]

